import numpy as np


class C10EdgeDE:
    """Feasibility-rule mixed-integer DE that drives the search onto the constraint-10 edge.

    Changes over BoundaryPushDE:
      * Constraint-10 target violation rate raised to ~50%, with a wider probe-rate range.
      * Probes use two overshoot directions (isotropic Gaussian and population difference),
        larger overshoot factors, and a 4-step bisection back to the constraint-10 edge.
      * Every constraint-10-violating probe point is inserted into the population, so
        the population keeps material that lies just beyond the feasible boundary.
      * Constraint 10 is up-weighted in the infeasible ranking.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng()
        d = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        span = ub - lb
        types = [str(func.variable_types[i]) for i in range(d)]
        is_int = np.array([t != "continuous" for t in types], dtype=bool)
        cont = ~is_int
        ncont = int(cont.sum())
        int_idx = np.flatnonzero(is_int)
        nvals = np.ones(d, dtype=int)
        for i in int_idx:
            nvals[i] = int(func.n_values[i])
        cat_mask = np.array([t == "categorical" for t in types], dtype=bool)

        W10 = 2.5
        TARGET_C10 = 0.50
        st = {"evals": 0, "bf": np.inf, "bx": None, "bg": None, "c10_hist": []}
        wts = {"w": None}
        p_probe = {"p": 0.3}

        def can_eval():
            return st["evals"] < budget

        def decode(g):
            x = lb + g * span
            x[is_int] = g[is_int]
            return x

        def repair(g):
            g = g.copy()
            g[cont] = np.clip(g[cont], 0.0, 1.0)
            if len(int_idx):
                g[is_int] = np.clip(np.rint(g[is_int]), 0, nvals[is_int] - 1)
            return g

        def random_genome():
            g = np.empty(d)
            g[cont] = rng.random(ncont)
            if len(int_idx):
                g[is_int] = rng.integers(0, nvals[is_int]).astype(float)
            return g

        def mutate_int(u):
            if len(int_idx) and rng.random() < 0.5:
                k = int(rng.choice(int_idx))
                if cat_mask[k]:
                    u[k] = float(rng.integers(nvals[k]))
                else:
                    u[k] = float(np.clip(u[k] + rng.choice([-1.0, 1.0]), 0, nvals[k] - 1))
            return u

        def evaluate(g):
            x = decode(g)
            f, gc = func(x)
            st["evals"] += 1
            f = float(f)
            gc = np.asarray(gc, dtype=float).ravel()
            if wts["w"] is None or len(wts["w"]) != len(gc):
                ww = np.ones(len(gc))
                if len(gc) >= 10:
                    ww[9] = W10
                wts["w"] = ww
            if np.any(np.isnan(gc)):
                vt, vr, c10 = 1e10, 1e10, True
            else:
                pos = np.maximum(gc, 0.0)
                vt = float(pos.sum())
                vr = float((wts["w"] * pos).sum())
                c10 = len(gc) >= 10 and gc[9] > 0
            if not np.isfinite(f):
                f = np.inf
                vt = max(vt, 1e10)
                vr = max(vr, 1e10)
            hist = st["c10_hist"]
            hist.append(bool(c10))
            if len(hist) > 300:
                del hist[:-300]
            if vt == 0.0 and f < st["bf"]:
                st["bf"] = f
                st["bx"] = x.copy()
                st["bg"] = g.copy()
            return {"f": f, "vt": vt, "vr": vr, "c10": bool(c10), "g": g.copy()}

        def better(a, b):
            if a["vt"] == 0.0 and b["vt"] == 0.0:
                return a["f"] < b["f"]
            if a["vt"] == 0.0 or b["vt"] == 0.0:
                return a["vt"] == 0.0
            return a["vr"] < b["vr"]

        def worst_index(pop):
            wj = 0
            for j in range(1, len(pop)):
                if better(pop[wj], pop[j]):
                    wj = j
            return wj

        def best_index(pop):
            bi = 0
            for j in range(1, len(pop)):
                if better(pop[j], pop[bi]):
                    bi = j
            return bi

        def c10_rate():
            h = st["c10_hist"]
            return float(np.mean(h[-200:])) if h else 0.0

        def insert(pop, rec):
            wj = worst_index(pop)
            if better(rec, pop[wj]):
                pop[wj] = rec

        def probe(base, pop):
            """Overshoot the feasible base past constraint 10, then bisect back to the edge."""
            s = rng.uniform(0.05, 0.35)
            t = rng.uniform(1.5, 3.0)
            out = base.copy()
            if rng.random() < 0.5 or len(pop) < 2:
                step = rng.normal(size=ncont)
            else:
                r1, r2 = rng.choice(len(pop), 2, replace=False)
                diff = pop[r1]["g"][cont] - pop[r2]["g"][cont]
                nrm = np.linalg.norm(diff)
                step = diff / nrm * np.sqrt(ncont) if nrm > 1e-12 else rng.normal(size=ncont)
            out[cont] = base[cont] + t * s * step
            if len(int_idx) and rng.random() < 0.3:
                out = mutate_int(out)
            out = repair(out)
            if not can_eval():
                return []
            r = evaluate(out)
            recs = [r]
            if not r["c10"]:
                return recs
            lo = base.copy()
            hi = out.copy()
            for _ in range(4):
                if not can_eval():
                    break
                mid = repair(0.5 * (lo + hi))
                mid[is_int] = base[is_int]
                rm = evaluate(mid)
                recs.append(rm)
                if rm["c10"]:
                    hi = mid
                else:
                    lo = mid
            return recs

        NP = int(np.clip(5 * d, 20, 60))
        pop = []
        for _ in range(NP):
            if not can_eval():
                return st["bf"], st["bx"]
            pop.append(evaluate(random_genome()))

        sigma = 0.1
        stall = 0

        while can_eval():
            xbest_rec = pop[best_index(pop)]
            xbest = xbest_rec["g"].copy()
            gbest = st["bg"] if st["bg"] is not None else xbest
            prev_bf = st["bf"]

            rate = c10_rate()
            p_probe["p"] = float(np.clip(p_probe["p"] * (1.04 if rate < TARGET_C10 else 0.96), 0.15, 0.7))

            if st["bg"] is not None and rng.random() < p_probe["p"] and can_eval():
                for rec in probe(gbest, pop):
                    insert(pop, rec)

            for i in range(NP):
                if not can_eval():
                    break
                u_r = rng.random()
                if u_r < 0.2:
                    u = gbest.copy()
                    m = cont & (rng.random(d) < 0.5)
                    if m.any():
                        u[m] += rng.normal(0.0, sigma, int(m.sum()))
                    u = mutate_int(u)
                    local = True
                elif u_r < 0.35 and st["bg"] is not None:
                    r1, r2 = rng.choice(NP, 2, replace=False)
                    tt = rng.uniform(1.2, 2.0)
                    u = gbest.copy()
                    u[cont] = gbest[cont] + tt * (pop[r1]["g"][cont] - pop[r2]["g"][cont])
                    u = mutate_int(u)
                    local = False
                else:
                    F = rng.uniform(0.4, 0.9)
                    CR = rng.uniform(0.1, 0.95)
                    others = np.delete(np.arange(NP), i)
                    r1, r2 = rng.choice(others, 2, replace=False)
                    xi = pop[i]["g"]
                    v = xi.copy()
                    v[cont] = xi[cont] + F * (xbest[cont] - xi[cont]) + F * (pop[r1]["g"][cont] - pop[r2]["g"][cont])
                    if len(int_idx):
                        pick = rng.random(d) < 0.5
                        vint = np.where(pick, xbest, pop[r1]["g"])
                        v[is_int] = vint[is_int]
                        reset = is_int & (rng.random(d) < 0.1)
                        for k in np.flatnonzero(reset):
                            v[k] = float(rng.integers(nvals[k]))
                    mask = rng.random(d) < CR
                    mask[rng.integers(d)] = True
                    u = xi.copy()
                    u[mask] = v[mask]
                    local = False

                u = repair(u)
                cand = evaluate(u)
                if local:
                    sigma *= 1.2 if better(cand, pop[i]) else 0.97
                    sigma = float(np.clip(sigma, 1e-4, 0.3))
                if not better(pop[i], cand):
                    pop[i] = cand

            if st["bf"] < prev_bf:
                stall = 0
            else:
                stall += 1

            if stall >= 30 and can_eval():
                bi = best_index(pop)
                for j in range(NP):
                    if not can_eval():
                        break
                    if j != bi and rng.random() < 0.5:
                        pop[j] = evaluate(random_genome())
                stall = 0
                sigma = 0.1

        return st["bf"], st["bx"]
